var C = ARISTO.colors;
var heads = 0;
var total = 0;
var history = []; // percentage of heads after each flip (sampled)

function fmtPct(p) {
  return (Math.round(p * 10) / 10).toString();
}

function sample() {
  // keep history length manageable: store every flip up to 300, then thin
  history.push(total === 0 ? 50 : (heads / total) * 100);
}

function doFlip() {
  var isHeads = Math.random() < 0.5;
  if (isHeads) heads++;
  total++;
  sample();
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (total === 0) {
    el.textContent = '0 flips — no data yet';
  } else {
    var pct = (heads / total) * 100;
    el.textContent = total + ' flip' + (total === 1 ? '' : 's') + ' — ' + heads + ' heads — ' + fmtPct(pct) + '% heads';
  }
}

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var padL = 34, padR = 10, padT = 10, padB = 18;
  var innerW = w - padL - padR;
  var innerH = h - padT - padB;

  // axes
  ctx.strokeStyle = C.muted;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(padL, padT);
  ctx.lineTo(padL, padT + innerH);
  ctx.lineTo(padL + innerW, padT + innerH);
  ctx.stroke();

  // y gridlines at 0,25,50,75,100
  ctx.fillStyle = C.body;
  ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  [0, 25, 50, 75, 100].forEach(function (v) {
    var y = padT + innerH - (v / 100) * innerH;
    ctx.strokeStyle = C.line;
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(padL + innerW, y);
    ctx.stroke();
    ctx.fillText(String(v), padL - 4, y);
  });

  // dashed theoretical line at 50
  var y50 = padT + innerH - 0.5 * innerH;
  ctx.setLineDash([6, 4]);
  ctx.strokeStyle = C.warning;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(padL, y50);
  ctx.lineTo(padL + innerW, y50);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.warning;
  ctx.textAlign = 'left';
  ctx.fillText('50% (theoretical)', padL + 4, y50 - 10);

  // experimental line
  if (history.length > 0) {
    ctx.strokeStyle = C.accentText;
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    var n = history.length;
    for (var i = 0; i < n; i++) {
      var x = padL + (n === 1 ? innerW : (i / (n - 1)) * innerW);
      var y = padT + innerH - (history[i] / 100) * innerH;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // dot at last point
    var lastX = padL + innerW;
    var lastY = padT + innerH - (history[n - 1] / 100) * innerH;
    ctx.fillStyle = C.accentText;
    ctx.beginPath();
    ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
    ctx.fill();
  }

  // x axis label
  ctx.fillStyle = C.body;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText('flips: ' + total, padL + innerW / 2, h - 4);
}, 0.42);

function refresh() {
  updateReadout();
  plot.redraw();
}

document.getElementById('flip1').addEventListener('click', function () {
  doFlip();
  refresh();
});

document.getElementById('flip50').addEventListener('click', function () {
  for (var i = 0; i < 50; i++) doFlip();
  refresh();
});

document.getElementById('resetBtn').addEventListener('click', function () {
  heads = 0;
  total = 0;
  history = [];
  refresh();
});

refresh();
